            key = "progress_" + lang
            if variant == "progress-missing":
                item.pop(key, None)
            else:
                item[key] = "   " if variant == "progress-blank" else {"not": "display text"}
        elif variant in ("next-missing", "next-object"):
            key = "next_check_" + lang
            if variant == "next-missing":
                item.pop(key, None)
